package com.gathin.tvhome;
import android.content.Context;import android.os.*;import android.security.keystore.*;import android.util.Base64;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.*;
/** Device-local original hotspot credentials are encrypted, never logged or exported in plaintext. */
final class SettingsSessionSecrets {
 private static final String ALIAS="cleanyourtv.session.settings.originals";
 private static SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias(ALIAS))return (SecretKey)store.getKey(ALIAS,null);KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return generator.generateKey();}
 static void capture(Context c,Bundle original)throws Exception{capture(c,"hotspot.encrypted",original);}
 static void capture(Context c,String id,Bundle original)throws Exception{android.content.SharedPreferences p=c.getSharedPreferences("settings_session_undo",0);if(p.contains(id))return;Parcel parcel=Parcel.obtain();byte[] bytes;try{parcel.writeBundle(original);bytes=parcel.marshall();}finally{parcel.recycle();}Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());byte[] encrypted=cipher.doFinal(bytes);String value=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(encrypted,Base64.NO_WRAP);if(!p.edit().putString(id,value).commit())throw new IllegalStateException("Could not preserve original hotspot settings.");java.util.Arrays.fill(bytes,(byte)0);}
 static Bundle original(Context c)throws Exception{return original(c,"hotspot.encrypted");}
 static Bundle original(Context c,String id)throws Exception{String value=c.getSharedPreferences("settings_session_undo",0).getString(id,null);if(value==null)throw new IllegalStateException("No hotspot original recorded");String[] parts=value.split(":",-1);if(parts.length!=2)throw new IllegalStateException("Original hotspot record is invalid");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));byte[] bytes=cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP));Parcel parcel=Parcel.obtain();try{parcel.unmarshall(bytes,0,bytes.length);parcel.setDataPosition(0);return parcel.readBundle(SettingsSessionSecrets.class.getClassLoader());}finally{parcel.recycle();java.util.Arrays.fill(bytes,(byte)0);}}
 private SettingsSessionSecrets(){}
}
